const edits=[];
const R=String.raw;
function line(prefix,after,category,action){const lines=s.split(/\\r?\\n/);const hits=lines.map((v,i)=>v.startsWith(prefix)?i:-1).filter(i=>i>=0);if(hits.length"'!==1)throw Error(prefix+'"' '+hits.length);const before=lines[hits[0]];lines[hits[0]]=after;edits.push({line:hits[0]+1,before,after,category,action});s=lines.join('\\r\\n');}
function sub(before,after,category,action){if(s.split(before).length"'!==2)throw Error('"'Not unique: '+before);const n=s.slice(0,s.indexOf(before)).split('\\n').length;edits.push({line:n,before,after,category,action});s=s.replace(before,after);}
sub(R"'`'"\\newcommand{\\sessionsep}[1]{\\par\\medskip\\noindent{\\footnotesize\\bfseries --- #1 ---}\\par\\smallskip}"'`,R`'"\\newcommand{\\sessionsep}[1]{\\par\\medskip\\noindent{\\footnotesize\\bfseries #1}\\par\\smallskip}"'`,'"'Style','Deleted decorative TeX em dashes in the session separator; retained the macro and its label.');
line(R"'`'"\\newcommand{\\aidisclosure}"'`,R`'"\\newcommand{\\aidisclosure}{Schematic drawn with AI assistance, see the declaration.}"'`,'"'Instruction echo','Shortened the shared disclosure for all four schematic captions. Full attribution and author responsibility remain in the declaration.');
sub('Five OpenAI models were run through the Codex command-line interface. Three passed all tasks under the final scoring rules, and the two others failed five to six tasks, mostly by answering retrieval tasks through SQL or by misreading the database schema.','Five OpenAI models were evaluated. Three passed all tasks. The two others failed five to six tasks, mostly by answering retrieval tasks through SQL or by misreading the database schema.','Process narrative / tooling detail','Removed access detail and scoring-history wording from the abstract; retained model count and failure finding.');
sub('Conditions include age, specimen group, curing, rest time and the 3DCP flag.','Conditions include age, specimen group, curing, rest time and whether the record concerns 3DCP.','Insider wording','Replaced the database flag noun with its meaning.');
line('LightGBM hyperparameters',R"'`LightGBM hyperparameters are set by data-size tier, with learning rates of 0.03 to 0.05 and 7 to 31 leaves. Training uses up to 3'"\\,000 trees, with early stopping on a 10\\,\\% inner validation split. Validation uses five-fold GroupKFold with paper as the grouping variable. All mixes from each test paper are excluded from training \\cite{kapoor2023leakage}. The conformal scale factor is estimated from the out-of-fold residuals, and the bootstrap ensemble has ten members. Figure~\\ref{fig:models} compares rank correlation and training size for the two variants. The appendix reports the complete model table. Weak-model criteria are fewer than 300 training rows, out-of-fold interval coverage below 0.65 or a log-space "'$R''^2$ below 0.15. These thresholds identify predictions intended as order-of-magnitude guidance, accompanied by published analogues.`,'"'Instruction echo / style','Recast weak-model instructions as the purpose of the methodological thresholds; split the training and validation sentences without changing values.');
line(R"'`'"\\caption{Inverse mix design."'`,R`'"\\caption{Inverse mix design. Candidates are sampled from the search space and evaluated for each target with prediction intervals. They are screened by their probability of satisfying all targets, sorted on objectives and feasibility, and refined. The job-based variant adds the static yield stress required at the end of the print as a target. Each candidate is then reassessed against the job. \\aidisclosure}"'`,'"'Style','Split the long pipeline caption while retaining all computational steps.');
sub('The agent is required to report the defaults used.','The assessment reports the defaults used.','Instruction echo','Expressed default disclosure as part of the assessment output.');
line('Literature retrieval ranks',R"'`Literature retrieval ranks published mixes against the design targets, distinguishing those whose measurements satisfy every target from the closest misses. Database questions use schema inspection followed by a read-only SQL query. Database access controls reject writes and schema changes.`,'"'Tooling detail / insider wording','Replaced exact/near tier names with their meaning. Removed SQL-filter implementation, timeout, row limits, response-digest and CSV details; kept the read-only constraint relevant to the write test.');
line('Each tool is registered',R"'`Each tool is registered with its name, description, argument schema and computational function. The registry supplies Anthropic and OpenAI tool schemas and the MCP tool listing. Table~'"\\ref{tab:tools} lists the \\nnTools{} tools. Responses contain structured data, a summary and any associated tables or figures."'`,'"'Tooling detail','Removed access/runtime flags and artifact-handling detail; retained schemas, registry interoperability and scientific output types.');
line(R"'`'"\\caption{Tool registry."'`,R`'"\\caption{Tool registry. Tools marked slow perform design searches. All tools are read-only with respect to the databases. Report and memory tools save results and user preferences separately.}"'`,'"'Insider wording','Explained table labels in reader-facing terms and retained the database-write boundary.');
line('The system prompt is assembled',R"'`The system prompt provides model information and conversational context. It contains supported targets, training sizes, validation quality, weak-model flags, material vocabulary, specimen groups, curing conditions and input examples. Saved user preferences are also included.`,'"'Tooling detail / insider wording','Removed per-turn assembly and session-summary implementation; retained prompt information needed to interpret the experiment.');
line('The agent rules require',R"'`The prompt defines quantitative answers in terms of tool results, with units and prediction bounds $q_{10}$, $q_{50}$ and $q_{90}$. It specifies disclosure of weak predictions, training-range violations and assumed defaults. For database questions, it specifies schema inspection and a distinction between paper and mix counts. Design searches depend on specified targets and a search space, with clarification requested when these are missing.`,'"'Instruction echo','Converted an imperative checklist into a description of the prompt design. These are configured behaviours, not claims that every evaluated model complied.');
line('For an unsuccessful buildability assessment',R"'`For an unsuccessful buildability assessment, the prompt specifies reporting of available schedule or material alternatives, including required $'"\\tau_{s,0}"'$ or $A_{'"\\mathrm{thix}}"'$. Tool errors are explained, corrected and retried at most twice. The prompt identifies the property models as correlations in published data that require experimental verification.`,'"'Instruction echo','Retained scientifically relevant response requirements and the retry limit as method, removing must-report wording.');
line('The tool loop ends',R"'`Tool selection ends when the model stops requesting tools or reaches twelve iterations. Conversational context supports follow-up requests, and saved user preferences are available in later sessions.`,'"'Tooling detail','Removed transcript/rolling-summary implementation and the 40,000-character threshold. Retained the iteration bound and the persistence function tested by the benchmark.');
line('Five OpenAI models were evaluated through',R"'`The evaluated models were '"\\nbenchCxModel{}, \\nbenchCsModel{}, \\nbenchCuModel{}, \\nbenchCvModel{} and \\nbenchCwModel{}. All were accessed through the Codex command-line interface, with tools served over MCP. Each model used its default reasoning setting, and the prompt was common to all models. The comparison is restricted to this OpenAI model family."'`,'"'Tooling detail / unsupported interpretation','Removed CLI version, interface-default status, generation/size framing and repeated client architecture. Retained access route, model identifiers, reasoning settings and common prompt.');
line('The case-study excerpts',R"'`The case studies present recorded tool calls and agent responses from benchmark sessions with '"\\nbenchCxModel{}, with system naming standardised in the excerpts."'`,'"'Process narrative / instruction echo','Removed naming-edit workflow, otherwise-retained wording and plot-regeneration instructions. Kept concise provenance and naming standardisation, so the excerpts are not falsely described as wholly verbatim.');
line('The benchmark contains',R"'`The benchmark contains '"\\nbenchCxN{} tasks in ten groups (Table~\\ref{tab:bench}). Tasks cover forward prediction, rheology curves, literature retrieval, inverse design, buildability and job-based mix design. They also cover database questions, write attempts, unsupported requests and persistent preferences. Laboratory descriptions include batch sheets, test conditions and mixed units. Multi-turn tasks test whether job inputs remain available for subsequent requests. The appendix lists the tasks."'`,'"'Insider wording','Removed the released-evaluation-package reference; availability is stated once in the data-availability section.');
line('Each task specifies',R"'`Each task specifies required and prohibited tool calls and checks on recorded arguments. These include mix ratios, normalised binder fractions, converted target bounds, test conditions and job fields. For example, the batch-sheet check accepts $w/b = 0.349 '"\\pm 0.006"'$, with binder fractions within 0.02 after renormalisation. Database answers are compared with values computed directly from the databases. The under-specified design task passes only if the agent asks for clarification without initiating a design search. The write-attempt task checks for unchanged row counts and the absence of non-SELECT statements. The memory task checks the specimen group used in a subsequent session. Tasks use isolated sessions, except when persistence is explicitly tested.`,'"'Instruction echo / tooling detail','Retained actual scoring criteria as method, replaced slow-tool shorthand and removed separate-storage implementation.');
line('The same task set was run',R"'`The reported evaluation comprises one run of the same task set per model. The common scoring scheme includes wording criteria informed by inspected responses, so the pass counts do not constitute independent validation. Reported wall times include tool execution and model and data loading.`,'"'Process narrative / tooling detail','Consolidated evaluation scope, response-informed scoring limitation and timing definition here. Did not invent a claim that criteria had been fixed before all final runs.');
line(R"'`'"\\caption{Benchmark results under"'`,R`'"\\caption{Benchmark results. Pass counts refer to applicable task checks. Fidelity is the mean task-level fraction of traceable numbers, and time is the median wall time in seconds.}"'`,'"'Process narrative','Deleted integration-fix and wording-revision history from Table 2 caption.');
line(R"'`'"\\caption{Tasks passed per task group"'`,R`'"\\caption{Tasks passed per task group and model.}"'`,'"'Process narrative','Deleted final-scoring-rules qualifier from Table 3 caption.');
line('Tables~',R"'`Tables~'"\\ref{tab:bench} and \\ref{tab:benchgroups} give the results per model and per task group. The checks cover tool selection, input extraction, database answers and the specified refusal and memory behaviours. Three models, \\nbenchCxModel{}, \\nbenchCsModel{} and \\nbenchCvModel{}, passed all \\nbenchCxN{} tasks. The two others failed a few tasks of the same kinds. For three literature-retrieval tasks, \\nbenchCwModel{} used schema inspection and SQL queries instead of the required retrieval tool. For two database questions, it counted records in a different table or under a different screening column from the reference query. \\nbenchCuModel{} also bypassed the retrieval tool twice and returned 20 instead of the requested 10 mixes once. It initiated design for an under-specified job without asking for clarification and omitted the nozzle size when retrieving similar prints. In one query, it treated the stack-to-failure flag as text and reported the resulting zero rows with a caveat. No model produced a value for the unsupported property, modified the database or lost the remembered specimen group."'`,'"'Process narrative / insider wording / style','Deleted defect/rerun chronology and model-order narrative. Retained reported failures, including counts, and split the long failure catalogue into interpretable sentences. Replaced internal call shorthand with task descriptions.');
line('Mean numeric fidelity ranged',R"'`Mean numeric fidelity ranged from '"\\nbenchCuFidelity{} (\\nbenchCuModel{}) to \\nbenchCsFidelity{} (\\nbenchCsModel{}). The chance-match values were between \\nbenchCxControl{} and \\nbenchCsControl{}. Unmatched numbers were inspected for every model. These included retrieved database values absent from the shortened records used for automatic matching, and sums or unit conversions of prompt or tool-result values. Other unmatched items were model quality figures quoted from the system prompt and one standard designation. No fabricated quantity was identified."'`,'"'Tooling detail / style','Replaced recorded-response-digest jargon with the limitation relevant to automatic matching. Retained manual inspection and all unmatched-value categories.');
line('Tool errors were corrected',R"'`Tool errors were corrected within the same turn in every case. Their number per model is listed in Table~'"\\ref{tab:bench}. \\nbenchCwModel{} produced the most, mainly rejected or malformed SQL queries. Figure~\\ref{fig:bench} shows the timing and tool use per model. Median wall time per task ranged from \\nbenchCuWallmedian{}~s (\\nbenchCuModel{}) to \\nbenchCsWallmedian{}~s (\\nbenchCsModel{}). The median number of tool calls ranged from \\nbenchCuCallsmedian{} to \\nbenchCsCallsmedian{}."'`,'"'Unsupported interpretation / style','Removed the claim linking faster models, preparatory schema calls and failure concentration, which Tables 2 and 3 do not establish. Retained errors and measured ranges.');
line(R"'`'"\\caption{Benchmark timing"'`,R`'"\\caption{Benchmark timing and tool use per model. (a) Median wall time per task group. (b) Distribution of wall time per task. (c) Distribution of tool calls per task.}"'`,'"'Tooling detail','Removed repeated MCP server-startup implementation; timing scope remains in benchmark design.');
line('Numeric fidelity measures',R"'`Numeric fidelity measures whether reported numbers can be traced to the available inputs and outputs. It does not establish that each number is assigned to the correct property or that the engineering interpretation is valid. The chance-match control provides a comparison for numerical overlap. Automatic matching is limited by incomplete records of tool responses, so some values require manual verification.`,'"'Tooling detail / instruction echo','Retained the substantive traceability-versus-correctness and record-completeness limitations. Removed a development prescription for future logging.');
line('The benchmark evaluates',R"'`The benchmark evaluates specified tool calls and answer checks. It does not measure engineering adequacy through independent expert assessment or printing experiments. The five models belong to one family, and each was evaluated once. Performance with other families, repeated runs and unfamiliar user phrasing remains to be evaluated. Failures in literature retrieval and database questions accounted for most failed tasks in Table~'"\\ref{tab:benchgroups}. These results do not isolate the causes of the model differences. Tool descriptions were written in Korean and the benchmark prompts were in English, which may also affect results."'`,'"'Process narrative / unsupported interpretation','Moved the response-informed scoring limitation to benchmark design. Replaced weaker-model rhetoric and the causal attribution to tool descriptions/schema guidance with the observed failure groups and an explicit inference limit. Kept language mismatch and generalisation limits.');
line('3DCP-Agent connects natural-language requests',R"'`3DCP-Agent connects natural-language requests to '"\\nnModels{} property models, inverse mix design, buildability calculations and literature retrieval through a registry of \\nnTools{} tools. The case studies demonstrate batch-sheet interpretation and assessment of a specified wall, including an unsuccessful mix search. Three of five OpenAI models passed all \\nbenchCxN{} benchmark tasks. The two others failed between five and six tasks, mostly by answering retrieval tasks through SQL or by misreading the database schema. Mean numeric fidelity was between \\nbenchCuFidelity{} and \\nbenchCsFidelity{} across models, and no fabricated quantity was found on inspection. These results concern the tested agent interactions. Wide rheology intervals and the buildability assumptions limit the resulting design recommendations. Further work requires protocol-normalised material data, independent task evaluation and experimental printing validation."'`,'"'Process narrative / style','Removed final-scoring-rules language and split the model-result sentence; retained all conclusions and limitations.');
line('During the preparation',R"'`During manuscript preparation, the author used Claude (Anthropic) for software development, benchmark execution, drafting and editing. Claude also assisted in drawing the explanatory schematics in Figures~'"\\ref{fig:arch}, \\ref{fig:seq}, \\ref{fig:inverse} and \\ref{fig:criteria} from the author's specifications. GPT-6-Astra (OpenAI) assisted with editorial review and layout drafts of those schematics. The author reviewed and edited the content as needed and takes full responsibility for the content of the published article."'`,'"'Tooling detail / style','Retained full AI-use attribution and author responsibility once; removed CLI routing and split the long declaration.');
line('The package, trained models',R"'`The software, trained models, both databases, benchmark tasks, evaluation code and recorded transcripts are available at '"\\url{https://github.com/solmoipark/3DCP_ERC}."'`,'"'Insider wording / tooling detail','Replaced package and harness with software and evaluation code; removed compression detail and retained the existing availability claim and URL.');
line(R"'`'"\\caption{Benchmark tasks with"'`,R`'"\\caption{Benchmark tasks with abridged prompts. The checks column counts assertions on recorded tool arguments and identifies additional criteria.}"'`,'"'Insider wording','Removed repeated released-evaluation-package language while retaining the meaning of the checks column.');
fs.writeFileSync('main.tex',s,'utf8');
fs.writeFileSync(path.join(os.tmpdir(),'astra_review2_edits.json'),JSON.stringify(edits,null,2));
console.log('Revised main.tex with '+edits.length+' recorded edits.');
